    'mqtt': 'Configurer'
};

// JSON environment variable (prototype: configuration without pages yet)
function json(name, fallback) {
    const v = env.get(name);
    if (typeof v !== 'string' || v.trim() === '') {

        return fallback;
    }
    try {

        return JSON.parse(v);
    } catch (e) {
        node.warn(name + ': JSON invalide (' + e.message + ')');

        return fallback;
    }
}

// voice engine configuration (see lib/voice.js)
// prototype (version 0.1): one voice device and the devices given by environment variables,
// pages to configure them later
let satellites = {};
if (env.get('DKNR_VOICE_HOST')) {
    satellites[env.get('DKNR_VOICE_ID') || 'main'] = {
        'name': env.get('DKNR_VOICE_NAME') || 'Boîtier',
        'room': env.get('DKNR_VOICE_ROOM') || 'salon',
        'host': env.get('DKNR_VOICE_HOST'),
        'port': Number(env.get('DKNR_VOICE_PORT')) || 6053,
        'key': env.get('DKNR_VOICE_KEY') || ''
    };
}

msg.payload.voice = {
    // wyoming-vosk (speech to text) and wyoming-piper (text to speech)
    'vosk': env.get('DKNR_VOICE_VOSK') || 'dknr_voice_vosk:10300',
    'piper': env.get('DKNR_VOICE_PIPER') || 'dknr_voice_piper:10200',
    'voice': env.get('DKNR_VOICE_VOICE') || 'fr_FR-siwis-medium',
    // base URL of dknr-voice reached by the voice devices, to play the spoken answers
    'url': env.get('DKNR_VOICE_URL') || '',
    // voice: spoken answer for everything, sound: short sound for the orders
    'response': env.get('DKNR_VOICE_RESPONSE') === 'sound' ? 'sound' : 'voice',
    'satellites': satellites,
    // { "id": { "room": "...", "entities": ["source/parent/entity"] } }
    'devices': json('DKNR_VOICE_DEVICES', {})
};

return msg;

