// DKNR MQTT messages: entities catalog (discovery) and values (get)
// the voice engine reads the values from the catalog (questions)

const topic = global.get('mqtt.topic', 'default') || '';
const t = typeof msg.topic === 'string' ? msg.topic : '';

if (topic === '' || !t.startsWith(topic + '/')) {

    return;
}

const path = t.slice(topic.length + 1).split('/');
const action = path.shift();

let catalog = global.get('catalog', 'memoryOnly');
if (typeof catalog !== 'object' || catalog === null) {
    catalog = { 'sources': {}, 'parents': {}, 'entities': {}, 'values': {} };
    global.set('catalog', catalog, 'memoryOnly');
}

// empty retained message: removed
const empty = msg.payload === '' || msg.payload === null || (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
const object = typeof msg.payload === 'object' && msg.payload !== null && !Buffer.isBuffer(msg.payload);

if (action === 'discovery') {
    // source: topic / discovery / source
    if (path.length === 1) {
        if (empty) {
            delete catalog.sources[path[0]];
        } else {
            catalog.sources[path[0]] = object && msg.payload.title ? String(msg.payload.title) : path[0];
        }
    }
    // parent: topic / discovery / source / parent
    else if (path.length === 2) {
        const key = path.join('/');
        if (empty) {
            delete catalog.parents[key];
        } else {
            catalog.parents[key] = object && msg.payload.name ? String(msg.payload.name).replace(/_/g, ' ') : path[1];
        }
    }
    // entity: topic / discovery / source / parent / entity
    else if (path.length === 3) {
        const uid = path.join('/');
        if (empty) {
            delete catalog.entities[uid];
        } else if (object) {
            catalog.entities[uid] = {
                'name': String(msg.payload.name || path[2]),
                'group': String(msg.payload.group || ''),
                'type': String(msg.payload.type || ''),
                'unit': String(msg.payload.unit || ''),
                'options': typeof msg.payload.options === 'object' && msg.payload.options !== null ? msg.payload.options : {}
            };
            if (typeof catalog.sources[path[0]] !== 'string') {
                catalog.sources[path[0]] = path[0];
            }
        }
    }

    return;
}

// value: topic / get / source / parent / entity
if (action !== 'get' || path.length !== 3) {

    return;
}

const uid = path.join('/');
// empty retained message: value removed by the source
if (empty) {
    delete catalog.values[uid];

    return;
}
const value = Buffer.isBuffer(msg.payload) ? msg.payload.toString() : msg.payload;
catalog.values[uid] = value;

// entities used by the voice devices: last value kept across restarts,
// some sources do not retain their values (ex: RFXCom, Daikin)
const devices = global.get('describe.voice.devices', 'memoryOnly') || {};
let used = false;
for (const id in devices) {
    if (Array.isArray(devices[id].entities) && devices[id].entities.includes(uid)) {
        used = true;
        break;
    }
}
if (!used) {

    return;
}

let last = global.get('last', 'default') || {};
if (last[uid] !== value) {
    last[uid] = value;
    global.set('last', last, 'default');
}

return;

// voice engine: see the "On Start" tab and lib/voice.js
// input: action = start (connect the voice devices) | test (payload = recognized sentence, ex: SET|test|1)
// output 1: DKNR commands (MQTT) / output 2: status changed (refresh of the pages)

const engine = context.get('engine', 'memoryOnly');
if (typeof engine !== 'object' || engine === null) {

    return;
}

if (msg.action === 'start') {
    await engine.start();
} else if (msg.action === 'test' && typeof msg.payload === 'string' && msg.payload.trim() !== '') {
    await engine.test(msg.payload.trim());
}

return;

