// voice engine (lib/voice.js, given by settings.js), created when the flow starts and closed when it stops
// output 1: DKNR commands (MQTT) / output 2: status changed (refresh of the pages)

const voice = global.get('lib_voice');
if (typeof voice !== 'object' || voice === null) {
    node.error('voice: lib/voice.js not loaded (see settings.js)');
    node.status({ 'fill': 'red', 'shape': 'dot', 'text': 'lib missing' });

    return;
}

// the previous engine (redeploy) must have closed its connections
const previous = global.get('voice_closing', 'memoryOnly');
if (previous && typeof previous.then === 'function') {
    try { await previous; } catch (e) { }
}

const texts = { 'online': 'connecté', 'connecting': 'connexion...', 'offline': 'déconnecté', 'error': 'erreur' };

const engine = voice.create({
    'config': () => Object.assign({}, global.get('describe.voice', 'memoryOnly') || {}, {
        'topic': global.get('mqtt.topic', 'default') || 'dknr'
    }),
    'publish': (topic, payload) => node.send([{ 'topic': topic, 'payload': payload, 'qos': 0, 'retain': false }, null]),
    // value of an entity: current one, or the last one known before restart
    'valueOf': (uid) => {
        const values = (global.get('catalog', 'memoryOnly') || {}).values || {};

        return values[uid] !== undefined ? values[uid] : (global.get('last', 'default') || {})[uid];
    },
    'onStatus': (status) => {
        global.set('voice_status', status, 'memoryOnly');
        const sats = Object.values(status.satellites);
        node.status({
            'fill': sats.length > 0 && sats.every(s => s.state === 'online') ? 'green' : (sats.length === 0 ? 'grey' : 'red'),
            'shape': 'dot',
            'text': sats.map(s => s.name + ' : ' + (texts[s.state] || s.state)).join(', ') || 'aucun boîtier'
        });
        node.send([null, { 'topic': 'status' }]);
    },
    'log': {
        'info': (m) => node.log(m),
        'warn': (m) => node.warn(m),
        'error': (m) => node.error(m),
        'debug': (m) => node.debug(m)
    }
});

context.set('engine', engine, 'memoryOnly');
global.set('voice_engine', engine, 'memoryOnly');
node.status({ 'fill': 'grey', 'shape': 'dot', 'text': 'waiting' });

finalize:
// close the connections to the voice devices, the next engine waits for it (see "On Start")
const engine = context.get('engine', 'memoryOnly');
if (typeof engine === 'object' && engine !== null && typeof engine.close === 'function') {
    global.set('voice_closing', engine.close(), 'memoryOnly');
}
global.set('voice_engine', null, 'memoryOnly');

