// spoken answer (WAV) asked by a voice device: url given in the TTS_END event of the session

const engine = global.get('voice_engine', 'memoryOnly');
const wav = engine ? engine.answer(msg.req.params.file) : null;

if (!wav) {
    msg.statusCode = 404;
    msg.headers = { 'Content-Type': 'text/plain' };
    msg.payload = 'not found';

    return msg;
}

msg.statusCode = 200;
msg.headers = { 'Content-Type': 'audio/wav', 'Content-Length': wav.length, 'Cache-Control': 'no-store' };
msg.payload = wav;

return msg;

// Boîtiers page: voice devices and last sentences
// output 1: voice devices table / output 2: last sentences table

const status = global.get('voice_status', 'memoryOnly') || { 'satellites': {}, 'history': [] };
const cfg = global.get('describe.voice', 'memoryOnly') || {};

const texts = { 'online': 'Connecté', 'connecting': 'Connexion...', 'offline': 'Déconnecté', 'error': 'Erreur' };
const time = t => new Date(t).toLocaleTimeString('fr-FR', { 'timeZone': env.get('TZ') || 'Europe/Paris', 'hour': '2-digit', 'minute': '2-digit', 'second': '2-digit' });

let sats = Object.values(status.satellites || {}).map(s => ({
    'name': s.name,
    'room': s.room,
    'host': s.host,
    'state': (texts[s.state] || s.state) + (s.busy ? ' (écoute)' : '') + (s.error ? ' : ' + s.error : ''),
    'since': s.since ? time(s.since) : ''
}));
if (sats.length === 0) {
    sats = [{ 'name': 'Aucun boîtier configuré (variable DKNR_VOICE_HOST)', 'room': '', 'host': '', 'state': '', 'since': '' }];
}
if (!cfg.url) {
    sats.push({ 'name': 'Variable DKNR_VOICE_URL manquante : les boîtiers ne pourront pas lire les réponses', 'room': '', 'host': '', 'state': '', 'since': '' });
}

const history = (status.history || []).map(h => ({
    'time': time(h.time),
    'satellite': h.satellite,
    'heard': h.heard || '-',
    'action': h.action || '-',
    'say': (h.ok ? '' : '⚠ ') + (h.say || ''),
    'ms': h.ms ? (h.ms / 1000).toFixed(1).replace('.', ',') + ' s' : ''
}));

return [{ 'payload': sats }, { 'payload': history }];
